  group(
    'Phase 5.3 ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â Nearest Branch Selection',
    () {
      test(
        'nearestBranch returns the CLOSEST branch when multiple exist',
        () async {
          final fakeFirestore = FakeFirebaseFirestore();

          // Seed two branches at different distances from user
          await fakeFirestore.collection('branches').doc('branch_near').set({
            'name': 'Branch Near',
            'lat': 25.21, // ~0.6 miles from user at 25.2048
            'lng': 55.2708,
            'deliveryRadiusMiles': 5.0,
            'isDefault': false,
          });
          await fakeFirestore.collection('branches').doc('branch_far').set({
            'name': 'Branch Far',
            'lat': 25.50, // ~20+ miles from user
            'lng': 55.2708,
            'deliveryRadiusMiles': 5.0,
            'isDefault': false,
          });

          final nearDocs = await fakeFirestore.collection('branches').get();
          final allDocs = nearDocs.docs
              .map((e) => e as DocumentSnapshot)
              .toList();

          final service = BranchService(
            fakeFirestore,
            logger: LoggerService(),
            fetchBranchesOverride: (lat, lng) async => allDocs,
          );

          final nearest = await service.nearestBranch(25.2048, 55.2708);

          expect(nearest, isNotNull);
          expect(
            nearest!.name,
            equals('Branch Near'),
            reason:
                'The algorithm must always return the NEAREST branch, not an arbitrary one',
          );
        },
      );

      test('nearestBranch returns null when no branches exist', () async {
        final fakeFirestore = FakeFirebaseFirestore();
        final service = BranchService(
          fakeFirestore,
          logger: LoggerService(),
          fetchBranchesOverride: (lat, lng) async => [],
        );
        final nearest = await service.nearestBranch(25.2048, 55.2708);
        expect(
          nearest,
          isNull,
          reason:
              'When branch list is empty, nearestBranch must return null, not crash',
        );
      });
    },
  );
}
